+}
+
+/// The skill without its `checksum` line: what the checksum is computed
+/// over, and what a skill rendered before checksums is compared with.
+fn without_checksum(contents: &str) -> String {
+    if !contents.starts_with("---") {
+        return contents.to_string();
+    }
+    let mut out = String::with_capacity(contents.len());
+    let mut lines = contents.split_inclusive('\n');
+    out.push_str(lines.next().unwrap_or_default());
+    let mut in_frontmatter = true;
+    for line in lines {
+        if line.trim_end() == "---" {
+            in_frontmatter = false;
+        }
+        if !(in_frontmatter && is_checksum_line(line)) {
+            out.push_str(line);
+        }
+    }
+    out
+}
