+/// Adds `metadata.checksum`, the SHA-256 of `unchecksummed`, as the last
+/// line of its frontmatter — `metadata` is the last key `render` writes.
+fn with_checksum(unchecksummed: &str) -> String {
+    let checksum = sha256_hex(unchecksummed.as_bytes());
+    let line = format!("  checksum: \"{checksum}\"\n");
+    match unchecksummed.get(1..).and_then(|rest| rest.find("\n---\n")) {
+        Some(at) => {
+            let close = at + 2; // past the `-` skipped and the `\n` before `---`
+            format!(
+                "{}{line}{}",
+                &unchecksummed[..close],
+                &unchecksummed[close..]
+            )
+        }
+        None => unchecksummed.to_string(),
+    }
+}
